+import fs from 'node:fs';
+const [file,out]=process.argv.slice(2), launch=JSON.parse(fs.readFileSync(file));
+if(!launch.profile.endsWith('/.cache/cross-mode/p01/v0572/craft-focus-clearance-preparation/run/profile')||!launch.endpoint.startsWith('ws://127.0.0.1:'))throw Error('Wrong owned browser');
